// Structural transport only: no customer rules, SQL templates or execution.
const raw = $input.first().json || {};
const payload = raw.body;
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const validText = (value, max) => typeof value === 'string' && value.trim().length > 0 && value.length <= max;
if (!record(payload) || payload.contract_version !== '1') {
  throw new Error('SHADOW_ENVELOPE_CONTRACT_REJECTED');
}
const correlation = payload.correlation_metadata;
const principal = payload.principal;
if (!record(correlation) || !record(principal)) {
  throw new Error('SHADOW_ENVELOPE_IDENTITY_REJECTED');
}
const paths = {
  generate: '/v1/internal/sql-agent/generate',
  execute_approved: '/v1/internal/sql-agent/execute-approved-shadow'
};
const routes = {
  generate: '/api/generate-sql',
  execute_approved: '/api/execute-watson'
};
const event = correlation.event;
if (!Object.prototype.hasOwnProperty.call(paths, event) ||
    correlation.source !== 'nextjs_bff' || correlation.route !== routes[event] ||
    !validText(correlation.request_id, 128) ||
    !validText(correlation.timestamp, 64) ||
    !validText(payload.agent_run_id, 128) ||
    !validText(principal.id, 256) || !validText(principal.profile, 128)) {
  throw new Error('SHADOW_ENVELOPE_CORRELATION_REJECTED');
}
const outbound = {
  contract_version: '1',
  agent_run_id: payload.agent_run_id,
  principal: {
    id: principal.id,
    profile: principal.profile,
    ...(validText(principal.email, 320) ? {email: principal.email} : {})
  },
  correlation_metadata: {
    source: correlation.source,
    event,
    route: correlation.route,
    timestamp: correlation.timestamp,
    request_id: correlation.request_id,
    ...(validText(correlation.agent_version, 128)
      ? {agent_version: correlation.agent_version} : {})
  }
};
if (event === 'generate') {
  if (!validText(payload.question, 16000)) {
    throw new Error('SHADOW_ENVELOPE_QUESTION_REJECTED');
  }
  outbound.question = payload.question;
} else {
  if (!validText(payload.approved_sql, 262144)) {
    throw new Error('SHADOW_ENVELOPE_APPROVED_SQL_REJECTED');
  }
  outbound.approved_sql = payload.approved_sql;
}
return [{json: {
  event,
  agent_run_id: payload.agent_run_id,
  target_path: paths[event],
  shadow_request: outbound
}}];

const transport = $input.first().json || {};
const response = transport.body || {};
const source = $('Validate Shadow Envelope').first().json;
const validObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
if (!validObject(response) ||
    !(transport.statusCode === 200 || transport.statusCode === 422) ||
    response.contract_version !== '1' ||
    response.agent_run_id !== source.agent_run_id ||
    typeof response.run_id !== 'string' || !response.run_id ||
    !['success', 'rejected'].includes(response.status) ||
    (transport.statusCode === 200 && response.status !== 'success') ||
    (transport.statusCode === 422 && response.status !== 'rejected')) {
  throw new Error('LANGGRAPH_SHADOW_GENERATE_RESPONSE_REJECTED');
}
return [{json: {
  agent_run_id: source.agent_run_id,
  event: source.event,
  run_id: response.run_id,
  status: response.status
}}];

const transport = $input.first().json || {};
const body = transport.body || {};
const source = $('Validate LangGraph Response').first().json;
const expectedType = source.event === 'generate' ? 'generate' : 'execute_approved_shadow';
if (transport.statusCode !== 200 ||
    !body || body.agent_run_id !== source.agent_run_id ||
    !Array.isArray(body.items)) {
  throw new Error('LANGGRAPH_SHADOW_EVIDENCE_LOOKUP_REJECTED');
}
const records = body.items.filter(item =>
  item && item.agent_run_id === source.agent_run_id &&
  item.run_id === source.run_id &&
  item.event_type === expectedType &&
  item.status === source.status &&
  typeof item.shadow_record_id === 'string' && item.shadow_record_id.length > 0
);
if (records.length !== 1) {
  throw new Error('LANGGRAPH_SHADOW_EVIDENCE_CORRELATION_REJECTED');
}
return [{json: {
  correlated: true,
  agent_run_id: source.agent_run_id,
  run_id: source.run_id,
  shadow_record_id: records[0].shadow_record_id,
  event: source.event,
  status: source.status
}}];
